// 原Growth原支付后step的路由回归：真实扣时/完成只一次，新profile不再走旧完成减伤。
#include "resident/domains/growth/growth_recovery_services.hpp"
#include "resident/domains/growth/growth_internal.hpp"
#include <iostream>
#include <stdexcept>
#include <type_traits>
using namespace hanmo::resident;
namespace {int checks=0;void check(bool v,const char* s){++checks;if(!v)throw std::runtime_error(s);}struct Observer final:GrowthPersonalRecoveryServices{Integer periods=0,closes=0;Status preview(const CommonStore&,const StableId&,const GrowthQuote&)const override{return common_success();}Outcome<GrowthQuote> preview_cancel(const CommonStore&,const GrowthState&,const StableId&,const GrowthCommand&)const override{return {false,{},common_failure("UnusedTestHook").error};}Outcome<GrowthEffect> cancel(CommonStore&,GrowthState&,const StableId&,const GrowthQuote&)override{return {false,{},common_failure("UnusedTestHook").error};}Status started(CommonStore&,GrowthState&,const ActionCoreView&)override{return common_success();}Status provided(CommonStore& c,GrowthState&,const ActionCoreView& action)override{check(c.action(action.id)&&c.action(action.id)->remaining_ticks==1,"credit must precede original decrement");++periods;return common_success();}Status completed(CommonStore&,GrowthState& g,const ActionCoreView& action)override{check(g.life_activities.find(action.id)->view.phase==LifeActivityPhase::completed,"closure must follow original completion");++closes;return common_success();}};
using Finish=Outcome<GrowthEffect>(*)(CommonStore&,GrowthState&,const GrowthCatalog&,SocialState&,InteractionState&,const ActionCoreView&,const GrowthPersonalRecoveryServices*);
static_assert(std::is_same_v<decltype(&growth::finish_service_trade),Finish>,"same declared/defined service hook signature");
void run(bool selected){auto catalog=std::make_shared<CommonCatalog>();CommonState seed;seed.identity.tick=0;ActorRecord actor;actor.id="patient";actor.alive=actor.available=true;actor.hp=85;actor.injury=1;actor.wallet_id="patient_wallet";actor.action_id="action:1";seed.actors.insert(actor.id,actor);seed.wallets.insert("patient_wallet",{"patient_wallet",{Owner::Kind::actor,"patient",{},{}},80,{},{}});seed.wallets.insert("provider_wallet",{"provider_wallet",{Owner::Kind::actor,"provider",{},{}},20,{},{}});ActionCoreView action{"action:1","service","patient",{"patient","provider"},0,1};seed.actions.insert(action.id,action);CommonStore c(seed,catalog);GrowthCatalog growth_catalog;growth_catalog.regional_life=true;GrowthState growth;GrowthAction payload;payload.request.kind="service";payload.request.activity="rest";ServiceTerms terms;terms.duration=1;terms.cost=20;terms.hp_gain=35;terms.wallet_id="provider_wallet";payload.quote.data=terms;growth.actions.insert(action.id,payload);LifeActivityRecord life;life.view.action_id=life.view.fact_id=action.id;life.view.actor_id="patient";life.view.kind=LifeActivityKind::service;life.view.activity="rest";life.view.start_tick=0;life.terms=terms;growth.life_activities.insert(action.id,life);SocialState social;InteractionState interaction;GrowthAccess access;Observer observer;if(selected)access.personal_recovery=&observer;auto result=step_growth(c,growth,growth_catalog,*catalog,social,interaction,access,action);check(result.ok&&result.value.completed,"original service completes");check(c.action(action.id)->remaining_ticks==0,"original action decremented exactly once");check(observer.periods==(selected?1:0)&&observer.closes==(selected?1:0),"selected pointer only invokes real hooks");const auto* final=c.state().actors.find("patient");check(final->injury==(selected?1:0)&&final->hp==(selected?90:100),"new source owns injury and cap; old profile unchanged");check(c.wallet("patient_wallet")->balance==80&&c.wallet("provider_wallet")->balance==20,"finish does not pay prepaid price again");}}
int main(){try{run(false);run(true);std::cout<<"GROWTH_RECOVERY_SERVICE_HOOKS "<<checks<<" checks 0 failures\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
